import {AUTH} from './hosting.mjs';
import {VERSION,CATEGORIES,ROLES,STEPS,CSV_HEADER,clone,addDays,daysBetween,weekday,effectiveDate,derived,schedule,priorityParts,forecast,planRecords,validateSettings,validateStudy,validateRecord,newRecord,validateImport,csvCell} from './domain.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={today:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',board:'M4 4h16v16H4z M4 9h16 M9 9v11',shipments:'M3 7h12v11H3z M15 11h4l3 4v3h-7 M6 18a2 2 0 1 0 0 .1 M18 18a2 2 0 1 0 0 .1',studies:'M9 3h6 M10 3v6L4 19q-1 2 1 2h14q2 0 1-2L14 9V3 M8 14h8',data:'M4 5c0-4 16-4 16 0s-16 4-16 0v14c0 4 16 4 16 0V5 M4 12c0 4 16 4 16 0',team:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-3a4 4 0 0 0-3-4',pilot:'M9 3h6v4h-6z M8 5H5v16h14V5h-3 M8 12h8 M8 16h5',about:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 11v6 M12 7v1',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',check:'M5 12l4 4L19 6',plus:'M12 4v16 M4 12h16',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',arrow:'M5 12h14 M13 6l6 6-6 6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[n]||icons.board).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
const NAV={today:'Today',board:'Workboard',shipments:'Shipment forecast',studies:'Studies & calendars',data:'Data & settings',team:'Team & history',pilot:'Usability pilot',about:'Project notes'};
const S={w:null,version:0,session:null,sandbox:false,error:null,scope:'mine',query:'',category:'all',status:'open',study:'all',page:'today',audit:[],auditNext:null,snapshots:[],pilot:[],import:null,policy:null,capacity:null,volume:null,delay:null,saving:false,selected:null};
const can=r=>S.session?.member.roles.includes('admin')||S.session?.member.roles.includes(r);
const dateLabel=(d,long=false)=>new Intl.DateTimeFormat('en-US',{month:long?'long':'short',day:'numeric',timeZone:'UTC',...(long?{year:'numeric'}:{})}).format(new Date(d+'T12:00:00Z'));
const timeLabel=t=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:S.w?.settings.timezone||'America/Phoenix'}).format(new Date(t));
const model=()=>({...S.w,settings:{...S.w.settings,capacity:S.capacity??S.w.settings.capacity,policy:S.policy??S.w.settings.policy,volume:S.volume??S.w.settings.volume,delay:S.delay??S.w.settings.delay}});
const records=()=>S.w.records.map(r=>derived(r,S.w));
const memberName=id=>id?(S.session.members.find(x=>x.id===id)?.name||'Inactive member'):'Unassigned';
const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function setConnection(text,error=false){$('#connection').textContent=text;$('#connection').classList.toggle('error',error);}
let toastTimer;function toast(message,error=false){$('#toast').textContent=message;$('#toast').className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',6000);}
async function api(path,body){if(S.sandbox)return sandboxApi(path,body);const res=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Trialflow-Request':'1'}:{},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await res.json();}catch{throw new Error('The server response could not be read. Refresh and try again.');}if(!res.ok){const e=new Error(data.error||'Request failed');e.status=res.status;e.details=data.details||[];throw e;}return data;}
async function save(path,body){if(S.saving)throw new Error('A save is already in progress');S.saving=true;setConnection(S.sandbox?'Training change…':'Saving…');try{const res=await api(path,{version:S.version,...body});if(res.workspace){S.w=res.workspace;S.version=res.version;}setConnection(S.sandbox?'Training sandbox · unsaved':'Saved to shared database');return res;}catch(e){setConnection('Not saved',true);throw e;}finally{S.saving=false;}}
function shell(){S.page=location.hash.slice(1).split('?')[0]||'today';if(!NAV[S.page])S.page='today';$('#navigation').innerHTML=Object.entries(NAV).map(([key,label])=>`<a href="#${key}" class="${S.page===key?'active':''}" ${S.page===key?'aria-current="page"':''}>${icon(key)}${label}</a>`).join('');$('#breadcrumb').textContent=NAV[S.page];$('#session-controls').innerHTML=S.sandbox?'<a href="/" target="_top" class="account-link">Shared workspace ↗</a>':S.session?`<a href="${esc(AUTH.accountPath)}" target="_top" class="account-link">${esc(AUTH.accountLabel)}</a>`:`<a href="${esc(AUTH.signInPath)}" target="_top" class="account-link">Sign in ↗</a>`;$('#identity').textContent=S.session?.member.name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('')||'TF';$('#identity').title=S.session?`${S.session.member.name}\n${S.session.member.roles.map(r=>ROLES[r]).join(', ')}`:'Not signed in';if(S.w)$('.workspace-label>div').innerHTML=`${esc(S.w.settings.siteName.split(' · ')[0])}<small>${S.sandbox?'Browser training sandbox':'Private pilot workspace'}</small>`;}
function render(){shell();if(!S.session)return gate();if(!S.w)return initializeView();const view={today:todayView,board:boardView,shipments:shipmentsView,studies:studiesView,data:dataView,team:teamView,pilot:pilotView,about:aboutView}[S.page];$('#main').innerHTML=(S.sandbox?`<div class="sandbox-banner"><span><b>Training sandbox.</b> Changes last only until this page reloads. No shared saves or verified sign-offs.</span>${button('Exit sandbox','exit-sandbox','small')}</div>`:'')+view();if(S.page==='team')loadHistory();if(S.page==='data'&&can('admin'))loadSnapshots();if(S.page==='pilot')loadPilot();}
function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="kicker">${kicker}</p><h1 class="serif">${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function gate(){const authError=S.error?.status===403;$('#main').innerHTML=`<section class="gate"><p class="kicker">A PRIVATE SITE OPERATIONS LAB</p><h1>Every follow-up.<br>A clearer next step.</h1><p>Coordinate study deadlines, sample shipments, report review and QC<br>in one traceable synthetic-data workspace.</p>${S.error&&![401].includes(S.error.status)?`<div class="notice red">${esc(S.error.message)}</div>`:''}<div class="row-stack"><a class="btn primary" href="${esc(authError?AUTH.switchPath:AUTH.signInPath)}" target="_top">${esc(authError?AUTH.switchLabel:AUTH.signInLabel)} ↗</a>${button('Explore training sandbox','sandbox')}</div><div class="notice">Shared records require a verified sign-in and an approved workspace role. The training sandbox uses invented fixtures and keeps changes in memory. This pilot does not connect to an EDC or interpret clinical findings.</div></section>`;}
function initializeView(){$('#main').innerHTML=heading('WELCOME TO TRIALFLOW','Make space for clearer work.','Start a shared pilot workspace with three fictional studies and example site tasks.')+`<div class="panel"><div class="panel-body"><div class="empty">${icon('studies')}<h2>${can('admin')?'Your private workspace is ready to initialize':'The workspace has not been initialized'}</h2><p>This one-time setup creates three fictional studies and example site tasks in the shared database.<br>Investigator review, QC and filing remain separate; historical examples are labelled unverified.</p><ol class="setup-steps"><li><b>Initialize</b><span>Create the shared synthetic workspace below.</span></li><li><b>Review the calendars</b><span>Adjust planned visits and pickup days to your scenario.</span></li><li><b>Generate shipment tasks</b><span>Review the forecast and add its expected batches to the workboard.</span></li><li><b>Record a check</b><span>Open a task and record the next permitted step. The dashboard updates after saving.</span></li></ol>${can('admin')?`<form data-form="initialize"><label class="check-label"><input type="checkbox" name="ack" required>I will use synthetic operational data only. I understand this is a pilot.</label><div class="form-error" role="alert"></div><button class="btn primary">Initialize synthetic workspace ${icon('arrow')}</button></form>`:'Ask the site owner to initialize the pilot.'}</div></div></div>`;}
function safetyBanner(){const flags=records().filter(r=>r.source?.flagged&&r.type==='saes'),open=flags.filter(r=>!r.complete);return `<div class="safety-banner">${icon('alert')}<div><strong>${flags.length} source SAE flags · ${open.length} local follow-ups open</strong><p>Flagged source events stay visible after checklist completion. Follow approved safety procedures; these dates are synthetic operational targets.</p></div>${button('View flags →','safety-filter','small')}</div>`;}
function statsView(){const rr=records(),open=rr.filter(r=>!r.complete),sc=schedule(model());return `<div class="stats">${[[open.length,'Open follow-ups',`${rr.filter(r=>r.complete).length} workflows completed`,'board',''],[open.filter(r=>r.overdue).length,'Overdue items','Past the local operational target','clock','warning'],[open.filter(r=>r.hold).length,'QC holds','Resolve evidence, then pass QC','alert',''],[sc.filter(r=>r.atRisk&&!r.overdue).length,'At risk of delay','Estimated from available capacity','today','']].map(([n,l,sub,i,c])=>`<div class="stat ${c}"><span class="stat-label">${l}</span><span class="stat-icon">${icon(i)}</span><div class="stat-number">${n}</div><small>${sub}</small></div>`).join('')}</div>`;}
function taskStatus(r){if(r.complete)return badge('Completed','green');if(r.hold)return badge('QC hold','amber');if(r.overdue)return badge('Overdue','red');const scheduled=schedule(model()).find(x=>x.id===r.id);if(scheduled?.atRisk)return badge('At risk','amber');return badge('On track','green');}
function taskTable(rr,compact=false){if(!rr.length)return `<div class="empty">${icon('check')}No matching tasks. Adjust filters or add a synthetic task.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Task / study</th><th>Due</th><th>Status</th>${compact?'':'<th>Assigned to</th>'}<th>Next action</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${rr.map(r=>`<tr class="clickable" data-record="${esc(r.id)}"><td><a href="#${S.page}" class="task-name" data-action="detail" data-id="${esc(r.id)}">${esc(r.title)}</a><div class="task-meta"><span class="study-dot" style="background:${esc(r.study?.color)}"></span>${esc(r.study?.code)}<span>·</span>${esc(CATEGORIES[r.type])}</div></td><td class="${r.overdue?'date-red':''}">${dateLabel(r.dueDate)}<div class="task-meta">${r.overdue?`${daysBetween(r.dueDate,effectiveDate(S.w.settings))}d overdue`:r.dueDate===effectiveDate(S.w.settings)?'Today':r.dueDate.slice(0,4)}</div></td><td>${taskStatus(r)}</td>${compact?'':`<td>${esc(memberName(r.assignee))}</td>`}<td>${r.complete?'Filed & checked':r.hold?'Resolve QC evidence':esc(r.next?.label)}<div class="row-progress" aria-label="${r.done} of ${r.total} checks complete">${Array.from({length:r.total},(_,i)=>`<i class="${i<r.done?'done':''}"></i>`).join('')}</div></td><td><button class="btn link" data-action="detail" data-id="${esc(r.id)}" aria-label="Open ${esc(r.title)}">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function firstUsePanel(){
 const planned=S.w.records.filter(r=>r.planKey).length;
 const recorded=S.w.records.reduce((n,r)=>n+r.steps.filter(s=>S.session.members.some(m=>m.id===s.actorId)).length,0);
 if(planned&&recorded)return '';
 const missing=planRecords(S.w).filter(e=>!e.existing).length;
 return `<details class="panel start-panel" open><summary>Start using your ${S.sandbox?'training':'shared'} workspace <span>${S.sandbox?'Changes are temporary':'Changes save to the shared database'}</span></summary><div class="start-grid"><div><span class="kicker">01 · STUDY CALENDARS</span><strong>${S.w.studies.length} fictional studies ready to review</strong><p>Set visit patterns, sample quantities and pickup days.</p><a class="btn small" href="#studies">Review calendars →</a></div><div><span class="kicker">02 · SHIPMENT WORK</span><strong>${missing} expected batches need task records</strong><p>Review generation to bring forecast batches into the queue.</p>${can('crc')?button('Review shipment tasks','plan','small'): '<a class="btn small" href="#shipments">View forecast →</a>'}</div><div><span class="kicker">03 · PROGRESS & QC</span><strong>${recorded} checks recorded here</strong><p>Open a task to record review, QC and filing separately.</p><a class="btn small" href="#board">Open workboard →</a></div></div></details>`;
}
function todayView(){const date=effectiveDate(S.w.settings),rr=records(),sc=schedule(model()),ranked=[...sc,...rr.filter(r=>r.hold&&!r.complete)],scope=ranked.filter(r=>S.scope==='team'||S.scope==='mine'&&r.assignee===S.session.member.id||S.scope==='unassigned'&&!r.assignee);const visible=scope.slice(0,8);return heading('YOUR DAILY OPERATIONS BRIEF','Your site, in focus.',`${dateLabel(date,true)} · ${esc(S.w.settings.siteName)}${S.w.settings.simulationDate?' · Simulation date':''}`,`${button('Import CSV','import')} ${can('crc')?button(`${icon('plus')} Add task`,'new-record','primary'):''}`)+firstUsePanel()+statsView()+safetyBanner()+`<div class="grid-main"><div><section class="panel"><div class="panel-head"><div><h2>What needs your attention</h2><p>Priority order across the site. QC holds remain visible.</p></div><a class="btn link" href="#board">All tasks ↗</a></div><div class="section-tabs">${[['mine','My work'],['team','Site team'],['unassigned','Unassigned']].map(([id,l])=>`<button data-action="scope" data-scope="${id}" class="${S.scope===id?'active':''}">${l}<small>${ranked.filter(r=>id==='team'||id==='mine'&&r.assignee===S.session.member.id||id==='unassigned'&&!r.assignee).length}</small></button>`).join('')}</div>${taskTable(visible,true)}<div class="table-foot"><span>Showing ${visible.length} of ${scope.length} open tasks</span><span>SAE follow-ups retain priority</span></div></section><section class="panel"><div class="panel-head"><div><h2>Upcoming operational deadlines</h2><p>Next seven calendar days · submissions and monitoring actions</p></div></div>${taskTable(rr.filter(r=>['regulatory','monitoring'].includes(r.type)&&!r.complete&&r.dueDate>=date&&r.dueDate<=addDays(date,7)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,4),true)}</section></div><aside class="right-rail">${forecastCard()}${scenarioCard()}</aside></div>`;}
function scenarioCard(){const m=model(),sc=schedule(m),base=schedule(S.w),policy=m.settings.policy;return `<section class="side-card"><span class="eyebrow">WORKLOAD EXPLORER</span><h3 style="margin-top:8px">A different day, a different queue.</h3><p>Try a capacity or priority change. This preview does not move deadlines or change saved tasks.</p><label class="control-label" for="capacity-range">Available hours / workday <output>${m.settings.capacity}h</output></label><input id="capacity-range" data-scenario="capacity" type="range" min="1" max="16" step=".5" value="${m.settings.capacity}"><div class="control-label">Prioritization policy</div><div class="policy-chips">${[['risk','Impact'],['deadline','Deadline'],['short','Shortest']].map(([id,n])=>`<button data-action="policy" data-policy="${id}" class="${policy===id?'active':''}">${n}</button>`).join('')}</div><div class="mini-row"><span>Predicted late follow-ups</span><b>${sc.filter(r=>r.atRisk).length} <span style="font-weight:400;color:#9caa8c">/ baseline ${base.filter(r=>r.atRisk).length}</span></b></div><p style="margin-bottom:10px">One pooled team, sequential tasks, working-day estimates. QC holds are excluded; they need human resolution.</p>${button('Reset preview','reset-scenario','link')}</section>`;}
function forecastCard(){const f=forecast(model()),days=f.calendar.slice(0,7),max=Math.max(1,...days.flatMap(d=>['fresh','frozen'].map(k=>f.events.filter(e=>e.dispatchDate===d&&e.kind===k).reduce((a,e)=>a+e.quantity,0))));return `<section class="side-card"><div class="row-stack" style="justify-content:space-between"><h3>Samples on the horizon</h3>${badge('14 DAYS','green')}</div><p>Predicted pickups from planned visits<br>and study-level shipping rules.</p><div class="big-number">${f.events.reduce((a,e)=>a+e.quantity,0)} <small>tubes to dispatch</small></div><div class="legend"><span>Fresh</span><span>Frozen</span></div><div class="chart" role="img" aria-label="Seven-day fresh and frozen shipment forecast. Exact quantities are available in Shipment forecast.">${days.map(d=>`<div class="chart-day"><div class="chart-bars">${['fresh','frozen'].map(k=>{const n=f.events.filter(e=>e.dispatchDate===d&&e.kind===k).reduce((a,e)=>a+e.quantity,0);return `<i class="${k}" style="height:${n/max*90}px" title="${d}: ${n} ${k} tubes"></i>`;}).join('')}</div><small>${['S','M','T','W','T','F','S'][weekday(d)]}</small></div>`).join('')}</div><div class="mini-row"><span>Planned visits</span><b>${f.visits}</b></div><div class="mini-row"><span>Frozen remaining after horizon</span><b>${f.waiting} tubes</b></div><a class="btn link" href="#shipments" style="margin-top:12px">Explore shipment plan →</a></section>`;}
function boardView(){const rr=records(),ranks=new Map(schedule(model()).map(r=>[r.id,r.rank]));let filtered=rr.filter(r=>(S.category==='all'||r.type===S.category)&&(S.study==='all'||r.studyId===S.study)&&(S.status==='all'||S.status==='open'&&!r.complete||S.status==='completed'&&r.complete||S.status==='hold'&&r.hold||S.status==='overdue'&&r.overdue||S.status==='risk'&&schedule(model()).some(x=>x.id===r.id&&x.atRisk&&!r.overdue))&&(!S.query||[r.title,r.study?.code,r.id,CATEGORIES[r.type]].join(' ').toLowerCase().includes(S.query.toLowerCase())));filtered.sort((a,b)=>(ranks.get(a.id)||9999)-(ranks.get(b.id)||9999)||a.dueDate.localeCompare(b.dueDate));return heading('SITE WORKBOARD','One queue. Every follow-up.','Open a task to review evidence, record the next check, or resolve a QC hold.',`${button('Export tasks','export-csv')}${can('crc')?button(`${icon('plus')} Add task`,'new-record','primary'):''}`)+safetyBanner()+`<div class="filters"><input id="search" data-filter="query" placeholder="Search tasks, studies or IDs…" aria-label="Search tasks" value="${esc(S.query)}"><select data-filter="category" aria-label="Filter category"><option value="all">All categories</option>${Object.entries(CATEGORIES).map(([k,v])=>`<option value="${k}" ${S.category===k?'selected':''}>${v}</option>`).join('')}</select><select data-filter="study" aria-label="Filter study"><option value="all">All studies</option>${S.w.studies.map(s=>`<option value="${esc(s.id)}" ${S.study===s.id?'selected':''}>${esc(s.code)}</option>`).join('')}</select><select data-filter="status" aria-label="Filter status">${[['open','Open tasks'],['all','All statuses'],['overdue','Overdue'],['risk','At risk'],['hold','QC holds'],['completed','Completed']].map(([k,v])=>`<option value="${k}" ${S.status===k?'selected':''}>${v}</option>`).join('')}</select></div><section class="panel">${taskTable(filtered)}<div class="table-foot"><span>${filtered.length} matching tasks</span><span>Changes save after each recorded check</span></div></section>`;}
function shipmentsView(){const w=model(),f=forecast(w),plan=planRecords(w),missing=plan.filter(e=>!e.existing),mismatch=plan.filter(e=>e.existing&&(e.existing.quantity!==e.quantity||e.existing.forecastDispatchDate!==e.dispatchDate));return heading('SHIPMENT PLANNING','See the next pickup coming.','A 14-day operational forecast. Volumes and dates are estimates, with no sample-viability assessment.',`${can('crc')?button('Review generated tasks','plan','primary'):''}`)+`<div class="stats">${[[f.visits,'Planned visits'],[f.freshCollected,'Fresh tubes collected'],[f.frozenCollected,'Frozen tubes collected'],[f.waiting,'Frozen tubes remaining']].map(([n,l])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-number">${n}</div><small>Based on current scenario assumptions</small></div>`).join('')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Pickup forecast</h2><p>${f.events.length} predicted study batches · ${missing.length} missing task records</p></div></div><div class="table-wrap"><table><thead><tr><th>Study / samples</th><th>Planned</th><th>Predicted dispatch</th><th>Tubes</th><th>Task record</th></tr></thead><tbody>${plan.map(e=>`<tr><td><span class="task-name">${esc(S.w.studies.find(s=>s.id===e.studyId)?.code)}</span>${badge(e.kind,e.kind==='fresh'?'green':'amber')}</td><td>${dateLabel(e.date)}</td><td class="${e.dispatchDate>e.date?'date-red':''}">${dateLabel(e.dispatchDate)}</td><td>${e.quantity}</td><td>${e.existing?`<button class="btn link" data-action="detail" data-id="${esc(e.existing.id)}">${e.existing.quantity!==e.quantity||e.existing.forecastDispatchDate!==e.dispatchDate?'Review changed assumptions ↗':'Open saved task ↗'}</button>`:badge('Not generated','gray')}</td></tr>`).join('')||'<tr><td colspan="5">No pickups predicted.</td></tr>'}</tbody></table></div><div class="table-foot"><span>Fresh waiting: ${f.freshWaiting} · Frozen waiting: ${f.waiting}</span><span>${mismatch.length} saved tasks differ from current assumptions</span></div></section><aside class="right-rail"><section class="side-card"><h3>Adjust the forecast</h3><label class="control-label" for="volume-range">Planned visit volume <output>${w.settings.volume}%</output></label><input id="volume-range" type="range" data-scenario="volume" min="0" max="300" step="10" value="${w.settings.volume}"><label class="control-label" for="delay-range">Courier delay <output>${w.settings.delay} workdays</output></label><input id="delay-range" type="range" data-scenario="delay" min="0" max="7" step="1" value="${w.settings.delay}"><p>Preview changes are temporary. Generated tasks use saved study and site settings.</p>${button('Reset preview','reset-scenario','link')}</section><section class="side-card dark"><span class="eyebrow">PLANNING ASSUMPTIONS</span><h3 style="margin-top:10px">Keep the rules visible.</h3><p>Weekly visit estimates × tubes per visit. Dated visit tasks override the estimate for that study and date. Frozen batches carry inventory between pickups; fresh batches accumulate to the next pickup.</p><p>These estimates do not validate packaging, stability, time-sensitive safety reporting or actual dispatch.</p><a class="btn small" href="#studies">Edit study calendars ↗</a></section></aside></div>`;}
function studiesView(){return heading('STUDIES & CALENDARS','Plans that match the study.','Set visit patterns, tube assumptions, pickup days and independent QC requirements.',can('crc')?button(`${icon('plus')} Add study`,'new-study','primary'):'')+`<div class="cards-3">${S.w.studies.map(s=>`<section class="panel study-card"><span class="study-code">${esc(s.code)}</span><h3>${esc(s.name)}</h3><p>Fictional study · ${S.w.records.filter(r=>r.studyId===s.id&&!derived(r,S.w).complete).length} open follow-ups</p><div class="mini-row"><span>Visits / typical week</span><b>${s.visits.reduce((a,b)=>a+b,0)}</b></div><div class="mini-row"><span>Tubes / visit</span><b>${s.fresh} fresh · ${s.frozen} frozen</b></div><div class="mini-row"><span>Frozen pickups</span><b>${s.frozenCadence==='twice'?s.frozenDays.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', '):'Every 14 days'}</b></div><div class="mini-row"><span>Visit window</span><b>±${s.windowDays} days</b></div><div class="mini-row"><span>Independent QC</span><b>${s.independentQC?'Required':'Solo pilot allowed'}</b></div>${can('crc')?button('Edit calendar →','edit-study','small',`data-id="${esc(s.id)}"`):''}</section>`).join('')}</div><div class="notice">The visit window is a planning parameter. A task’s due date is entered explicitly; the dashboard does not infer protocol compliance. Editing a calendar changes the forecast. It never silently overwrites started or completed shipment tasks.</div>`;}
function dataView(){const x=S.w.settings;return heading('DATA & SETTINGS','A workspace you can manage.','Validate inputs, save a restore point, and keep planning assumptions explicit.')+`<div class="data-grid"><section class="panel"><div class="panel-head"><div><h2>Bring work into the queue</h2><p>Validated synthetic CSV · up to 100 rows per import</p></div></div><div class="panel-body"><p class="subtitle">Preview every import. Invalid rows stop the whole import. Existing external IDs are rejected to prevent duplicate records.</p><div class="row-stack" style="margin-top:17px">${button('Download template','csv-template')}${can('crc')?button('Review CSV import','import','primary'):''}</div><div class="notice">Previous browser-only progress is retained in your browser. ${button('Download previous demo data','export-legacy','link')} exports it for reference; it is not treated as verified shared evidence.</div><div class="notice blue"><b>EDC: not connected.</b> This import is a manual operational task intake. It does not reconcile, close or write back EDC events. Live synchronization requires a named EDC, approved API access, field mappings and validation.</div></div></section><section class="panel"><div class="panel-head"><div><h2>Export & restore</h2><p>Versioned JSON snapshot and same-database restore points</p></div></div><div class="panel-body"><div class="row-stack">${button('Download workspace JSON','export-json')}${button('Export task CSV','export-csv')}${can('admin')?button('Create restore point','new-snapshot'):''}</div>${can('admin')?`<div id="snapshots-list" style="margin-top:15px"><span class="subtitle">Loading restore points…</span></div><div class="row-stack" style="margin-top:14px"><label class="btn small">Review JSON restore<input type="file" accept="application/json,.json" id="restore-file" class="sr-only"></label></div>`:''}<div class="notice">Restore points live in the same database. Download a copy for a separate backup. Restoring preserves team permissions and audit history, and records an automatic copy of the previous workspace.</div></div></section><section class="panel" style="grid-column:1/-1"><div class="panel-head"><div><h2>Site settings</h2><p>Shared baseline · temporary scenarios are separate</p></div></div><form data-form="settings"><div class="panel-body"><div class="form-grid">${field('Site name','siteName',x.siteName,'text','required maxlength="100"')}${field('Site timezone','timezone',x.timezone,'text','required', 'An IANA timezone, e.g. America/Phoenix. Dates use local calendar days.')}${field('Available hours / workday','capacity',x.capacity,'number','min="0.5" max="100" step="0.5" required')}${field('Baseline visit volume (%)','volume',x.volume,'number','min="0" max="300" required')}${field('Courier delay (workdays)','delay',x.delay,'number','min="0" max="14" required')}<div class="field"><label for="policy">Baseline prioritization</label><select id="policy" name="policy">${[['risk','Impact & urgency'],['deadline','Deadline first'],['short','Shortest first']].map(([k,v])=>`<option value="${k}" ${x.policy===k?'selected':''}>${v}</option>`).join('')}</select></div>${field('Optional simulation date','simulationDate',x.simulationDate,'date','','Leave blank to use today in the site timezone.')}<div class="field"><label>Site working weekdays</label>${dayChecks('workdays',x.workdays)}</div><div class="field full"><label for="holidays">Site holidays (one YYYY-MM-DD per line)</label><textarea id="holidays" name="holidays" rows="3">${esc(x.holidays.join('\n'))}</textarea></div>${field('Reason for baseline change','reason','','text','required maxlength="300"')}</div><div class="form-error" role="alert"></div>${can('admin')?'<button class="btn primary">Save shared settings</button>':'<p class="notice">An administrator can update shared settings.</p>'}</div></form></section></div>`;}
function teamView(){return heading('PEOPLE & TRACEABILITY','Know who did what.','Server-checked roles, timestamped evidence and a shared change history.',can('admin')?button(`${icon('plus')} Configure team member`,'new-member','primary'):'')+`<div class="notice">Workspace membership does not send an invitation or grant access to the private Site. Approved testers also need access through the Site’s sharing controls. Nobody has been invited by this build.</div><section class="panel"><div class="panel-head"><div><h2>Workspace roles</h2><p>Roles govern recorded checks, not professional credentials or clinical delegation.</p></div></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Permissions</th><th>Account binding</th><th></th></tr></thead><tbody>${S.session.members.map(m=>`<tr><td><span class="task-name">${esc(m.name)}</span><div class="task-meta">${esc(m.email)}</div></td><td>${m.roles.map(r=>badge(ROLES[r],r==='admin'?'blue':'gray')).join(' ')}</td><td>${!m.active?badge('Deactivated','red'):m.bound?badge('Signed-in account','green'):badge('Pending first sign-in','amber')}</td><td>${can('admin')&&m.id!==S.session.member.id?button('Edit','edit-member','small',`data-id="${esc(m.id)}"`):''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Change history</h2><p>Actor, role, server time, reason and before/after values. No delete endpoint.</p></div>${button('Export loaded history','export-audit','small')}</div><div class="panel-body" id="history-list"><p class="subtitle">Loading history…</p></div></section>`;}
const PILOT_TASKS=[['Find overdue work','Find an overdue query and identify its next required check.'],['Complete a review workflow','Record report review, QC and filing using permitted roles.'],['Resolve a QC hold','Resolve a synthetic evidence gap, then explicitly record QC.'],['Plan a frozen shipment','Change a study pickup rule and review the effect on the forecast.'],['Import and correct tasks','Preview a CSV, correct a validation error, then import valid rows.']];
function pilotView(){return heading('USABILITY PILOT','Test the workflow with people.','A lightweight workspace for 3–5 approved CRC testers using synthetic data.')+`<div class="grid-main"><div><section class="panel"><div class="panel-head"><div><h2>Suggested test tasks</h2><p>Start a timer, use the dashboard, then return here to record the outcome.</p></div></div><div class="panel-body">${PILOT_TASKS.map(([t,p])=>`<div class="pilot-task"><div><strong>${t}</strong><p>${p}</p></div>${button('Start task','start-pilot','small',`data-task="${esc(t)}"`)}</div>`).join('')}<div class="notice">Timing begins when you click Start. It includes time away from the screen. Outcomes and mistakes are self-reported. No screen recording or participant data is collected.</div></div></section><section class="panel"><div class="panel-head"><div><h2>Session results</h2><p>These are tester observations, not evidence of clinical validation.</p></div>${button('Export results','export-pilot','small')}</div><div id="pilot-results" class="panel-body"><p class="subtitle">Loading sessions…</p></div></section></div><aside class="right-rail"><section class="side-card dark"><span class="eyebrow">A SMALL, USEFUL STUDY</span><h3 style="margin-top:10px">Watch for friction.</h3><p>Give each tester the same tasks. Ask them to think aloud. Note incorrect clicks, unclear status labels, time to find work and whether they can distinguish QC completion from source-event closure.</p><p>Compare task completion, median time and ease ratings. Use observed problems to guide the next iteration.</p></section><section class="side-card"><h3>Before inviting testers</h3><p>Assign the minimum workspace role they need, then separately approve their private Site access. An independent QC study needs a second person with QC permission.</p><p>The owner has multiple roles for solo demonstration. That is not independent QC.</p></section></aside></div>`;}
function aboutView(){return heading('PROJECT NOTES','Clinical experience, made computational.','Trialflow · a site-level operations simulator and private synthetic-data pilot.')+`<section class="panel"><div class="panel-body project-prose" style="padding-top:24px"><h2>The problem</h2><p>A research site coordinates deadlines across shipments, regulatory submissions, monitoring findings, data queries, laboratory and EKG reports, drug accountability and safety follow-up. A task is only complete when its required human review, QC and filing steps are recorded.</p><h2>What the project computes</h2><p>Each record is a state machine with ordered checks. A server verifies the user’s role and prerequisites for each transition. Resolving a QC hold does not pass QC. Reopening a check clears its downstream evidence. Material edits restart recorded checks after explicit acknowledgement.</p><p>Priority uses an explainable rule: <code>urgency + operational impact + waiting age</code>. Urgency is bounded at 50 points; impact adds 8, 20 or 35; waiting age adds up to 15. Unblocked SAE follow-ups remain first under every policy. A sequential scheduler assigns remaining effort to working-day capacity; it estimates workload delay, not clinical risk or legal reporting times.</p><p>Shipment estimates use weekly visit patterns, dated visit overrides, tubes per visit, opening frozen inventory, pickup calendars and courier delay. The preview does not overwrite saved tasks. Generation only adds missing plan identifiers; changed assumptions on an existing task are surfaced for review.</p><h2>Engineering and validation</h2><p>JavaScript modules power the interface and shared validation. The same API supports two hosting adapters: a Cloudflare Worker with D1, or a Netlify Function using verified Netlify team login and a bounded SQLite snapshot in Netlify Blobs. Both store a versioned workspace, memberships, audit events, restore points and usability sessions. Compare-and-swap writes reject stale edits; changes and their audit records commit together. Netlify previews have separate storage from production.</p><p>Tests cover workflow prerequisites, role authorization, independent QC, duplicate imports, concurrent updates, source-status separation and restore behavior. Browser checks cover the task journey, form validation, imports and desktop layout. Mobile-device testing remains outstanding. An authenticated multi-user pilot and institutional validation remain future work.</p><h2>Responsible AI and data boundaries</h2><p>This version uses deterministic rules; it does not use machine learning or an LLM. Its scores are not calibrated clinical probabilities. The tool never interprets lab values or EKGs, diagnoses events, classifies reportability, submits safety reports or closes source AE/SAE records.</p><p>EDC is not connected. Source flags and local follow-up status are separate. Synthetic dates are operational examples, not regulatory deadlines. Only designated humans should make clinical and reporting decisions through approved study systems.</p><p>Use synthetic operational metadata only. Do not enter names, identifiers, medical narratives or clinical results. This is an instruction and scope limit, not an automated de-identification guarantee. Professional delegation, electronic signatures, retention policies, production security review and disaster recovery have not been validated for clinical use.</p><h2>Skills demonstrated</h2><p>Clinical workflow modeling; state machines; scheduling and simulation; data validation; SQL persistence; server-side authorization; optimistic concurrency; explainable decision support; audit design; accessible interface design; and task-based usability evaluation.</p><h2>Application explanation</h2><p>“I translated site-level clinical trial coordination into an interactive computational model. Trialflow represents operational work as ordered human-review and QC states, uses transparent scheduling rules to expose overdue and capacity-constrained work, and forecasts sample shipments from configurable study calendars. I added shared persistence, role checks, validated imports and traceable changes, with explicit boundaries around synthetic data and human clinical judgment.”</p><div class="notice">Use this explanation after reviewing the implementation and being able to discuss the design, tests and limitations yourself. Credit any assistance accurately in your application.</div><h2>Next step toward operational use</h2><p>Conduct a synthetic-data pilot, then work with the institution and sponsor on approved hosting, privacy and security review, access policies, retention, backup recovery, protocol-specific requirements and formal validation. A real EDC connector also needs the vendor, approved API or export access, study mappings, source timestamps, error handling and reconciliation tests.</p></div></section>`;}
function field(label,name,value='',type='text',attrs='',help=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" type="${type}" ${attrs}>${help?`<small>${help}</small>`:''}</div>`;}
function dayChecks(name,days){return `<div class="days-checks">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="${name}" value="${i}" ${days.includes(i)?'checked':''}>${d}</label>`).join('')}</div>`;}
function modal(title,subtitle,body,actions=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="close-dialog" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
function close(){$('#dialog').close();S.selected=null;}
function recordModal(id){const r=records().find(x=>x.id===id);if(!r)return;S.selected=id;const need=r.next?.role;const roleAllowed=need&&can(need);const independent=r.next?.qc&&r.study?.independentQC&&r.steps.some(s=>s.actorId===S.session.member.id);modal(esc(r.title),`${esc(r.study?.code)} · ${esc(CATEGORIES[r.type])} · ${esc(r.id)}`,`<div class="detail-meta">${taskStatus(r)}<strong>Due ${dateLabel(r.dueDate,true)}</strong><span class="subtitle">Assigned: ${esc(memberName(r.assignee))}</span></div><div class="notice"><b>Why this position?</b> ${Object.values(priorityParts(r,effectiveDate(S.w.settings))).reduce((a,b)=>a+b,0)} points: ${priorityParts(r,effectiveDate(S.w.settings)).urgency} urgency + ${priorityParts(r,effectiveDate(S.w.settings)).impact} impact + ${priorityParts(r,effectiveDate(S.w.settings)).age} waiting age. ${r.type==='saes'?'SAE precedence applies across policies. ':''}${r.hold?'Held tasks are excluded from workload scheduling.':r.complete?'All local checks are recorded.':`Estimated remaining effort: ${r.hours.toFixed(2)}h. Queue finish: ${(()=>{const x=schedule(model()).find(x=>x.id===r.id);return x?.predicted?dateLabel(x.predicted):'beyond the 180-workday model horizon';})()}.`}</div>${r.type==='shipments'?`<div class="notice">${r.quantity} ${r.sampleKind} tubes · ${esc(r.provenance)}${r.forecastDispatchDate?` · Forecast dispatch ${dateLabel(r.forecastDispatchDate)}`:''}</div>`:''}${r.source?`<div class="notice red"><b>Source flag: ${esc(r.source.status)}</b> · ${esc(r.source.origin)}<br>Local checklist completion never closes this source event. Use approved clinical and safety systems.</div><details><summary>Source record details</summary><div class="source-grid">${Object.entries(r.source).map(([k,v])=>`<div><span>${esc(k)}</span>${esc(v)}</div>`).join('')}</div></details>`:''}<ol class="step-list">${STEPS[r.type].map((s,i)=>{const done=i<r.done,evidence=r.steps[i];return `<li class="step-item ${done?'done':i===r.done?'current':''}"><span class="step-icon">${done?'✓':i+1}</span><div class="step-content"><div class="step-title">${esc(s.label)}</div><div class="step-detail">${ROLES[s.role]}${s.qc?' · QC check':''}${done?`<br>${esc(evidence.actorName)} · ${timeLabel(evidence.at)}<br>${esc(evidence.note)}`:''}</div></div>${done&&can('crc')?button('Reopen','reopen','link',`data-id="${esc(id)}" data-step="${i}"`):''}</li>`;}).join('')}</ol>${r.hold?`<div class="notice red"><b>QC hold:</b> ${esc(r.hold.reason)}<br>Resolving this hold returns the task to QC. It does not complete the QC check.</div>`:''}${!r.complete?`<form data-form="workflow" class="checks-form"><input type="hidden" name="id" value="${esc(id)}"><h3>${r.hold?'Resolve the evidence gap':`Next: ${esc(r.next.label)}`}</h3><p>${S.sandbox?'Training only. No verified sign-off is created.':`Your permitted roles: ${S.session.member.roles.map(x=>ROLES[x]).join(', ')}.`}${independent?' This study requires a different QC reviewer.':!r.hold&&!roleAllowed?` A user with ${ROLES[need]} permission must record this check.`:''}</p>${field('Synthetic evidence reference / action reason','reason','','text','required maxlength="300"', 'Reference only, e.g. SYN-DOC-042 v2. Do not enter participant details.')}<div class="form-error" role="alert"></div><div class="checks-actions">${r.hold?`<button name="action" value="resolve" class="btn primary" ${can('crc')?'':'disabled'}>Resolve hold</button>`:`<button name="action" value="complete" class="btn primary" ${roleAllowed&&!independent?'':'disabled'}>Record check complete</button>${r.next.qc?`<button name="action" value="hold" class="btn danger" ${can('qc')?'':'disabled'}>Record QC hold</button>`:''}`}</div></form>`:`<div class="notice"><b>All local checks completed.</b> ${r.source?'The source flag remains unchanged.':'The dashboard reflects this workflow as completed.'}</div>`}<details><summary>Traceability & record history</summary><p class="subtitle">${esc(r.provenance)} · Created ${timeLabel(r.createdAt)}. Server-recorded changes are available in Team & history.</p><div id="record-history" class="subtitle">Loading history…</div></details>`,`${button('Close','close')}${can('crc')?button('Edit / assign task','edit-record','',`data-id="${esc(id)}"`):''}`);loadRecordHistory(id);}
function recordForm(id=null){const r=id?S.w.records.find(x=>x.id===id):{type:'queries',studyId:S.w.studies[0]?.id,title:'',dueDate:effectiveDate(S.w.settings),assignee:S.session.member.id,impact:2,quantity:1,sampleKind:'fresh',plannedVisits:1,externalId:''};modal(id?'Edit task':'Add synthetic task','Operational metadata only. Clinical narratives and results do not belong in this pilot.',`<form data-form="record" id="record-form"><input type="hidden" name="id" value="${esc(id||'')}"><div class="form-grid"><div class="field"><label for="record-type">Category</label><select name="type" id="record-type" ${id?'disabled':''}>${Object.entries(CATEGORIES).map(([k,v])=>`<option value="${k}" ${r.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="record-study">Study</label><select name="studyId" id="record-study">${S.w.studies.map(s=>`<option value="${esc(s.id)}" ${r.studyId===s.id?'selected':''}>${esc(s.code)}</option>`).join('')}</select></div><div class="field full"><label for="record-title">Task title</label><input id="record-title" name="title" value="${esc(r.title)}" required maxlength="180"></div>${field('Operational due date','dueDate',r.dueDate,'date','required')}<div class="field"><label for="record-assignee">Assigned to</label><select id="record-assignee" name="assignee"><option value="">Unassigned</option>${S.session.members.filter(m=>m.active).map(m=>`<option value="${esc(m.id)}" ${r.assignee===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="record-impact">Operational impact</label><select id="record-impact" name="impact">${[[1,'Low'],[2,'Moderate'],[3,'High']].map(([k,v])=>`<option value="${k}" ${r.impact===k?'selected':''}>${v}</option>`).join('')}</select></div>${field('External task ID (optional)','externalId',r.externalId||'','text','maxlength="80"')}<div class="field shipment-field" ${r.type!=='shipments'?'hidden':''}><label for="record-kind">Sample type</label><select name="sampleKind" id="record-kind"><option value="fresh" ${r.sampleKind==='fresh'?'selected':''}>Fresh</option><option value="frozen" ${r.sampleKind==='frozen'?'selected':''}>Frozen</option></select></div><div class="field shipment-field" ${r.type!=='shipments'?'hidden':''}><label for="record-quantity">Tube count</label><input type="number" id="record-quantity" name="quantity" value="${r.quantity||1}" min="1" max="100000"></div><div class="field visit-field" ${r.type!=='visits'?'hidden':''}><label for="record-visits">Planned visits on this date</label><input type="number" id="record-visits" name="plannedVisits" value="${r.plannedVisits??1}" min="0" max="100"><small>Replaces the study’s weekly visit estimate for this date. Multiple visit tasks add together.</small></div></div>${id?field('Reason for change','reason','','text','required maxlength="300"'):''}${id&&(r.steps.length||r.hold)?'<label class="check-label"><input type="checkbox" name="resetEvidence">I understand changes to title, study, due date or quantities restart all recorded checks.</label>':''}<label class="check-label"><input type="checkbox" name="ack" required>This entry contains synthetic operational metadata only.</label><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" form="record-form">${id?'Save task':'Create task'}</button>`);}
function studyForm(id=null){const s=id?S.w.studies.find(x=>x.id===id):{code:'',name:'',visits:[0,2,2,2,2,1,0],fresh:2,frozen:2,initialFrozen:0,freshDays:[1,2,3,4,5],frozenDays:[2,5],frozenCadence:'twice',anchor:effectiveDate(S.w.settings),windowDays:3,independentQC:false};modal(id?'Edit study calendar':'Add synthetic study','These are planning assumptions, not protocol instructions.',`<form data-form="study" id="study-form"><input type="hidden" name="id" value="${esc(id||'')}"><div class="form-grid">${field('Study code','code',s.code,'text','required maxlength="30"')}${field('Study name','name',s.name,'text','required maxlength="100"')}<div class="field full"><label>Planned visits by weekday</label><div class="day-fields">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label>${d}<input name="visits" type="number" value="${s.visits[i]}" min="0" max="100" required aria-label="${d} planned visits"></label>`).join('')}</div></div>${field('Fresh tubes / visit','fresh',s.fresh,'number','min="0" max="50" required')}${field('Frozen tubes / visit','frozen',s.frozen,'number','min="0" max="50" required')}${field('Opening frozen inventory','initialFrozen',s.initialFrozen,'number','min="0" max="10000" required','Inventory assumed at the start of each rolling forecast, not a live inventory ledger.')}${field('Visit window (± days)','windowDays',s.windowDays,'number','min="0" max="60" required')}<div class="field full"><label>Fresh pickup weekdays</label>${dayChecks('freshDays',s.freshDays)}</div><div class="field"><label for="frozenCadence">Frozen cadence</label><select name="frozenCadence" id="frozenCadence"><option value="twice" ${s.frozenCadence==='twice'?'selected':''}>Selected weekdays</option><option value="fortnightly" ${s.frozenCadence==='fortnightly'?'selected':''}>Every 14 days (fortnightly)</option></select></div>${field('Fortnightly anchor date','anchor',s.anchor,'date','required')}<div class="field full"><label>Frozen pickup weekdays (weekday cadence)</label>${dayChecks('frozenDays',s.frozenDays)}</div></div><label class="check-label"><input name="independentQC" type="checkbox" ${s.independentQC?'checked':''}>Require independent QC: a QC reviewer cannot have performed an earlier check on the same task.</label><div class="notice">Changing these assumptions affects the forecast. Existing task quantities and completed checks stay unchanged until explicitly edited and reviewed.</div>${field('Reason / study setup reference','reason','','text','required maxlength="300"')}<div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button form="study-form" class="btn primary">Save calendar</button>`);}
function importModal(){S.import=null;modal('Review a synthetic CSV import','Preview and correct every row before adding work to the shared queue.',`<form data-form="import" id="import-form"><div class="row-stack">${button('Download template','csv-template','small')}<label class="btn small">Choose CSV<input type="file" accept=".csv,text/csv" id="csv-file" class="sr-only"></label></div><div class="field" style="margin-top:16px"><label for="csv-text">CSV contents</label><textarea id="csv-text" name="csv" rows="6" placeholder="Paste template contents here…" required></textarea><small>Up to 100 rows / 200 KB. Use existing study codes and active assignee emails. Leave assignee_email blank for unassigned work.</small></div>${button('Validate & preview','preview-import','primary small')}<div id="import-preview"></div><label class="check-label"><input type="checkbox" name="ack" required>I confirm all rows contain synthetic operational metadata only.</label><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" id="import-submit" form="import-form" disabled>Import validated rows</button>`);}
function previewImport(){const csv=$('#csv-text').value;try{const p=validateImport(csv,S.w,S.session.members);S.import={csv,...p};$('#import-preview').innerHTML=p.errors.length?`<div class="notice red"><b>${p.errors.length} row errors. Nothing will be imported.</b>${p.errors.map(e=>`<div>Row ${e.row}: ${esc(e.message)}</div>`).join('')}</div>`:`<div class="notice"><b>${p.records.length} valid rows ready.</b> Existing tasks will not be overwritten.</div><div class="table-wrap"><table><thead><tr><th>Task</th><th>Study</th><th>Due</th><th>Assignment</th></tr></thead><tbody>${p.records.map(r=>`<tr><td>${esc(r.title)}</td><td>${esc(S.w.studies.find(s=>s.id===r.studyId)?.code)}</td><td>${esc(r.dueDate)}</td><td>${esc(memberName(r.assignee))}</td></tr>`).join('')}</tbody></table></div>`;$('#import-submit').disabled=p.errors.length>0;}catch(e){S.import=null;$('#import-preview').innerHTML=`<div class="notice red">${esc(e.message)}</div>`;$('#import-submit').disabled=true;}}
function memberForm(id=null){const m=id?S.session.members.find(x=>x.id===id):{email:'',name:'',roles:['crc'],active:true};modal(id?'Edit workspace member':'Configure workspace member','This configures permissions only. It does not send an invitation or change private Site access.',`<form data-form="member" id="member-form"><input name="memberVersion" type="hidden" value="${m.version||0}"><div class="form-grid">${field('Approved member email','email',m.email,'email',`required maxlength="150" ${id?'readonly':''}`)}${field('Display name','name',m.name,'text','required maxlength="80"')}</div><span class="field-label">Workspace roles</span>${Object.entries(ROLES).map(([k,v])=>`<label class="check-label"><input type="checkbox" name="roles" value="${k}" ${m.roles.includes(k)?'checked':''}>${v}${k==='admin'?' · includes all permissions':k==='pi'?' · recorded investigator checks only; no credential verification':''}</label>`).join('')}<label class="check-label"><input type="checkbox" name="active" ${m.active?'checked':''}>Active membership</label>${field('Reason for membership change','reason','','text','required maxlength="300"')}<div class="notice">The first verified sign-in binds this email to the member’s Site-specific account ID. Separately grant approved testers access through the private Site’s sharing controls.</div><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button form="member-form" class="btn primary">Save permissions</button>`);}
function planModal(){const plan=planRecords(S.w),missing=plan.filter(e=>!e.existing);modal('Review shipment task generation','Uses saved settings and study calendars. Temporary scenario sliders are excluded.',`<div class="notice">${missing.length} new task records. Existing tasks, quantities, completed checks and assignments stay unchanged. Repeating generation does not duplicate the same study / sample type / planned date.</div><div class="table-wrap"><table><thead><tr><th>Study</th><th>Samples</th><th>Planned date</th><th>Tubes</th></tr></thead><tbody>${missing.map(e=>`<tr><td>${esc(S.w.studies.find(s=>s.id===e.studyId)?.code)}</td><td>${e.kind}</td><td>${dateLabel(e.date)}</td><td>${e.quantity}</td></tr>`).join('')||'<tr><td colspan="4">All predicted batches already have task records.</td></tr>'}</tbody></table></div><form data-form="plan" id="plan-form"><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" form="plan-form" ${missing.length?'':'disabled'}>Generate ${missing.length} tasks</button>`);}
function restoreModal(snapshotId=null,workspace=null){S.restore={snapshotId,workspace};modal('Review workspace restore','Administrator action. The current workspace will be replaced by the selected data.',`<div class="notice red">This replaces studies, settings, assignments and task progress for all users. Team permissions and audit history remain. An automatic pre-restore copy is saved in the same database.</div>${workspace?`<p class="subtitle">JSON preview: ${workspace.studies?.length??'?'} studies · ${workspace.records?.length??'?'} tasks. Imported evidence is marked unverified.</p>`:''}<form data-form="restore" id="restore-form">${field('Type RESTORE to confirm','confirm','','text','required pattern="RESTORE"')}${field('Reason for restore','reason','','text','required maxlength="300"')}<label class="check-label"><input type="checkbox" name="ack" required>I reviewed this restore and confirm the data is synthetic.</label><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button form="restore-form" class="btn danger">Restore workspace</button>`);}
function pilotStart(task){modal('Start usability task',esc(task),`<form data-form="pilot-start" id="pilot-start-form"><input type="hidden" name="task" value="${esc(task)}"><p class="subtitle">The timer starts when you confirm below. Continue working in the dashboard, then return to Usability pilot to finish and record your outcome.</p><label class="check-label"><input name="consent" type="checkbox" required>I agree to record my task time and self-reported feedback, using synthetic data only.</label><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" form="pilot-start-form">Start timer</button>`);}
function pilotFinish(id){const r=S.pilot.find(x=>x.id===id);modal('Finish usability task',esc(r?.data.task||''),`<form data-form="pilot-finish" id="pilot-finish-form"><input name="id" type="hidden" value="${esc(id)}"><div class="field"><label for="outcome">Outcome</label><select name="outcome" id="outcome"><option value="completed">Completed without help</option><option value="needed_help">Completed with help</option><option value="not_completed">Not completed</option><option value="cancelled">Cancelled</option></select></div><div class="field"><label for="rating">Ease of completing this task</label><select name="rating" id="rating" required><option value="">Choose 1–5</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} · ${['Very difficult','Difficult','Neutral','Easy','Very easy'][n-1]}</option>`).join('')}</select></div><div class="field"><label for="pilot-note">What was unclear? Any incorrect clicks or help needed?</label><textarea id="pilot-note" name="note" maxlength="300" rows="3" placeholder="Synthetic workflow observations only…"></textarea></div><div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" form="pilot-finish-form">Save outcome & stop timer</button>`);}
function historyMarkup(rows){return rows.map(r=>`<div class="history-entry"><strong>${esc(r.actor_name)}</strong> · ${esc(r.action)} · <code>${esc(r.entity_id)}</code><br><time>${timeLabel(r.at)} · ${r.roles.map(x=>ROLES[x]||x).join(', ')}</time><div>${esc(r.reason)}</div><details><summary>Before / after values</summary><pre>${esc(JSON.stringify({before:r.before,after:r.after},null,2))}</pre></details></div>`).join('')||'<div class="empty">No changes recorded yet.</div>';}
async function loadHistory(append=false){try{const data=await api('audit'+(append&&S.auditNext?`?before=${S.auditNext}`:''));S.audit=append?[...S.audit,...data.rows]:data.rows;S.auditNext=data.next;if(S.page==='team'&&$('#history-list'))$('#history-list').innerHTML=historyMarkup(S.audit)+(S.auditNext?button('Load older history','more-history','small'):'');}catch(e){if($('#history-list'))$('#history-list').innerHTML=`<p class="inline-error">${esc(e.message)}</p>`;}}
async function loadRecordHistory(id){try{const data=await api('audit');if(S.selected===id&&$('#record-history')){const rows=data.rows.filter(x=>x.entity_id===id);$('#record-history').innerHTML=historyMarkup(rows)+`<p class="subtitle">Filtered from the most recent 100 workspace changes. Older history can be loaded from Team & history.</p>`;}}catch(e){if($('#record-history'))$('#record-history').textContent=e.message;}}
async function loadSnapshots(){try{const data=await api('snapshots');S.snapshots=data.rows;if($('#snapshots-list'))$('#snapshots-list').innerHTML=data.rows.map(r=>`<div class="mini-row"><span>${esc(r.name)}<small style="display:block;margin-top:5px">${timeLabel(r.at)} · workspace v${r.workspace_version}</small></span>${button('Review restore','restore-snapshot','small',`data-id="${esc(r.id)}"`)}</div>`).join('')||'<p class="subtitle">No restore points yet.</p>';}catch(e){if($('#snapshots-list'))$('#snapshots-list').textContent=e.message;}}
async function loadPilot(){try{const data=await api('pilot');S.pilot=data.rows;const finished=data.rows.filter(x=>x.ended_at&&x.data.outcome!=='cancelled'),times=finished.map(x=>(Date.parse(x.ended_at)-Date.parse(x.started_at))/1000).sort((a,b)=>a-b);const mid=Math.floor(times.length/2),median=times.length?(times.length%2?times[mid]:(times[mid-1]+times[mid])/2):0;const rating=finished.length?finished.reduce((a,x)=>a+x.data.rating,0)/finished.length:0;if($('#pilot-results'))$('#pilot-results').innerHTML=`<div class="metrics-list"><div class="metric"><b>${finished.filter(x=>['completed','needed_help'].includes(x.data.outcome)).length}/${finished.length}</b><span>Tasks completed</span></div><div class="metric"><b>${Math.round(median)}s</b><span>Median task time</span></div><div class="metric"><b>${rating.toFixed(1)}/5</b><span>Mean ease rating</span></div></div>`+data.rows.map(r=>`<div class="history-entry"><strong>${esc(r.data.task)}</strong> · ${esc(memberName(r.actor_id))}<br><time>Started ${timeLabel(r.started_at)}${r.ended_at?` · ${Math.round((Date.parse(r.ended_at)-Date.parse(r.started_at))/1000)}s elapsed`:''}</time><p>${r.ended_at?`${esc(r.data.outcome.replaceAll('_',' '))} · Ease ${r.data.rating}/5<br>${esc(r.data.note)}`:`${badge('Timer running','amber')} ${r.actor_id===S.session.member.id?button('Finish task','finish-pilot','small',`data-id="${esc(r.id)}"`):''}`}</p></div>`).join('')+(data.rows.length?'':'<div class="empty">No usability sessions recorded. Start with one task above.</div>');}catch(e){if($('#pilot-results'))$('#pilot-results').textContent=e.message;}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportTasks(){const head=['task_id','study_code','type','title','due_date','assignee','workflow_status','checks_done','checks_total','source_status','quantity','sample_kind'];const data=records().map(r=>[r.id,r.study.code,r.type,r.title,r.dueDate,memberName(r.assignee),r.complete?'completed':r.hold?'qc_hold':'open',r.done,r.total,r.source?.status||'',r.quantity??'',r.sampleKind||'']);download('trialflow-tasks.csv',[head,...data].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');}
async function refresh(silent=false){if(S.saving)return;try{const [session,data]=await Promise.all([api('session'),api('workspace')]);S.session=session;if(!silent||data.version!==S.version){S.w=data.workspace;S.version=data.version;if(!$('#dialog').open)render();else if(silent)toast('Another session changed the workspace. Refresh before saving.');}setConnection(S.sandbox?'Training sandbox · unsaved':'Shared database · connected');}catch(e){if([401,403].includes(e.status)){S.session=null;S.w=null;S.version=0;S.error=e;close();render();setConnection('Sign-in required',true);}else setConnection('Connection unavailable',true);if(!silent)toast(e.message,true);}}
async function enterSandbox(){const data=await (await fetch('/api/training')).json();S.sandbox=true;S.error=null;S.w=data.workspace;S.version=1;S.audit=[];S.snapshots=[];S.pilot=[];S.session={member:{id:'sandbox',name:'Training user',email:'training@example.invalid',roles:['admin','crc','pi','qc'],active:true},members:[{id:'sandbox',name:'Training user',email:'training@example.invalid',roles:['admin','crc','pi','qc'],active:true,bound:false,version:1}]};setConnection('Training sandbox · unsaved');render();}
function sandboxApi(path,body){const p=path.split('?')[0];if(!body){if(p==='session')return S.session;if(p==='workspace')return {workspace:S.w,version:S.version};if(p==='audit')return {rows:S.audit,next:null};if(p==='snapshots')return {rows:S.snapshots};if(p==='pilot')return {rows:S.pilot};}const now=new Date().toISOString(),actor=S.session.member;if(body.version!=null&&body.version!==S.version)throw new Error('Training state changed. Refresh.');const before=clone(S.w);let entity='workspace',after=null;
 if(p==='records'){const old=S.w.records.find(r=>r.id===body.record.id);if(old){const v=validateRecord({...body.record,type:old.type},S.w,S.session.members);const critical=['title','studyId','dueDate','quantity','sampleKind','plannedVisits'].some(k=>old[k]!==v[k]);if(critical&&(old.steps.length||old.hold)&&!body.resetEvidence)throw new Error('Acknowledge that material edits restart checks');after={...old,...v,updatedAt:now,...(critical?{steps:[],hold:null}:{})};S.w.records[S.w.records.indexOf(old)]=after;}else{after=newRecord(body.record,S.w,S.session.members,actor.id,now);S.w.records.push(after);}entity=after.id;}
 else if(p==='workflow'){const r=S.w.records.find(x=>x.id===body.id);entity=r.id;if(body.action==='complete'){if(r.hold)throw new Error('Resolve the QC hold first');if(r.type==='shipments'&&r.planKey&&r.steps.length>=3&&effectiveDate(S.w.settings)<r.dueDate)throw new Error('Generated shipments cannot dispatch before the planned pickup date');const next=STEPS[r.type][r.steps.length];if(next.qc&&S.w.studies.find(s=>s.id===r.studyId).independentQC&&r.steps.some(s=>s.actorId===actor.id))throw new Error('Independent QC needs a different reviewer');r.steps.push({actorId:actor.id,actorName:'Training user · unverified',role:next.role,at:now,note:body.reason});}else if(body.action==='hold')r.hold={reason:body.reason,by:actor.id,at:now};else if(body.action==='resolve')r.hold=null;else if(body.action==='reopen'){r.steps=r.steps.slice(0,body.step);r.hold=null;}after=r;}
 else if(p==='settings'){S.w.settings=validateSettings(body.settings);after=S.w.settings;}
 else if(p==='studies'){const v=validateStudy(body.study,S.w.studies),i=S.w.studies.findIndex(s=>s.id===v.id);if(i<0)S.w.studies.push(v);else S.w.studies[i]=v;after=v;entity=v.id;}
 else if(p==='import'){const pre=validateImport(body.csv,S.w,S.session.members);if(pre.errors.length)throw new Error('Fix CSV validation errors');after=pre.records.map(r=>newRecord(r,S.w,S.session.members,actor.id,now));S.w.records.push(...after);}
 else if(p==='plan'){after=planRecords(S.w).filter(e=>!e.existing).map(e=>({...newRecord({studyId:e.studyId,type:'shipments',title:`${e.kind} shipment · ${e.date}`,dueDate:e.date,quantity:e.quantity,sampleKind:e.kind,impact:3},S.w,S.session.members,actor.id,now),planKey:e.key,forecastDispatchDate:e.dispatchDate,provenance:'Training forecast'}));S.w.records.push(...after);}
 else if(p==='snapshots'){const snap={id:crypto.randomUUID(),name:body.name,data:clone(S.w),at:now,actor_id:actor.id,workspace_version:S.version};S.snapshots.unshift(snap);return snap;}
 else if(p==='restore'){if(body.confirm!=='RESTORE')throw new Error('Type RESTORE to confirm');S.w=clone(body.workspace||S.snapshots.find(r=>r.id===body.snapshotId).data);after={restored:true};}
 else if(p==='members')throw new Error('Team membership is available in the signed-in shared workspace. No invitations are sent from training mode.');
 else if(p==='pilot'){if(body.action==='start'){const id=crypto.randomUUID();S.pilot.unshift({id,actor_id:actor.id,started_at:now,ended_at:null,data:{task:body.task}});return {id};}const r=S.pilot.find(x=>x.id===body.id);r.ended_at=now;r.data={...r.data,outcome:body.outcome,rating:Number(body.rating),note:body.note};return {id:r.id};}
 else throw new Error('This action is unavailable in training mode');S.version++;S.audit.unshift({seq:S.audit.length+1,id:crypto.randomUUID(),at:now,actor_id:actor.id,actor_name:'Training user · unverified',roles:actor.roles,action:p+(body.action?'.'+body.action:''),entity_id:entity,before:before.records.find(r=>r.id===entity)||null,after:clone(after),reason:body.reason||'Training change'});return {workspace:S.w,version:S.version};}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target){const row=e.target.closest('tr[data-record]');if(row)recordModal(row.dataset.record);return;}e.preventDefault();const a=target.dataset.action,id=target.dataset.id;try{
 if(a==='close')close();else if(a==='sandbox')await enterSandbox();else if(a==='exit-sandbox')location.reload();else if(a==='detail')recordModal(id);else if(a==='scope'){S.scope=target.dataset.scope;render();}else if(a==='safety-filter'){S.category='saes';S.status='all';location.hash='board';if(S.page==='board')render();}else if(a==='new-record')recordForm();else if(a==='edit-record')recordForm(id);else if(a==='new-study')studyForm();else if(a==='edit-study')studyForm(id);else if(a==='import')importModal();else if(a==='preview-import')previewImport();else if(a==='policy'){S.policy=target.dataset.policy;render();}else if(a==='reset-scenario'){S.policy=S.capacity=S.volume=S.delay=null;render();}else if(a==='plan')planModal();else if(a==='new-member')memberForm();else if(a==='edit-member')memberForm(id);else if(a==='more-history')await loadHistory(true);else if(a==='new-snapshot')modal('Create restore point','A same-database copy of studies, settings and task progress.',`<form data-form="snapshot" id="snapshot-form">${field('Restore point name','name','','text','required maxlength="100"')}<div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn primary" form="snapshot-form">Save restore point</button>`);else if(a==='restore-snapshot')restoreModal(id);else if(a==='reopen')modal('Reopen a completed check','This clears this check and every downstream check. The action is recorded in history.',`<form data-form="reopen" id="reopen-form"><input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="step" value="${target.dataset.step}">${field('Reason for reopening','reason','','text','required maxlength="300"')}<div class="form-error" role="alert"></div></form>`,`${button('Cancel','close')}<button class="btn danger" form="reopen-form">Reopen & clear downstream checks</button>`);else if(a==='csv-template')download('trialflow-import-template.csv',CSV_HEADER+'\r\n'+[`SYN-IMPORT-001`,S.w.studies[0].code,'queries','Synthetic date reconciliation',effectiveDate(S.w.settings),'','2','','',''].map(csvCell).join(',')+'\r\n','text/csv');else if(a==='export-json')download('trialflow-workspace-v3.json',JSON.stringify({format:'trialflow-workspace',version:VERSION,exportedAt:new Date().toISOString(),workspaceVersion:S.version,syntheticOnly:true,workspace:S.w},null,2));else if(a==='export-csv')exportTasks();else if(a==='export-legacy'){const saved=localStorage.getItem('trialflow-site-v2');if(!saved)throw new Error('No previous Trialflow demo progress is stored in this browser');download('trialflow-previous-browser-demo.json',saved);}else if(a==='export-audit')download('trialflow-loaded-history.json',JSON.stringify({scope:'Loaded history only',exportedAt:new Date().toISOString(),rows:S.audit},null,2));else if(a==='start-pilot')pilotStart(target.dataset.task);else if(a==='finish-pilot')pilotFinish(id);else if(a==='export-pilot')download('trialflow-usability-sessions.json',JSON.stringify({syntheticOnly:true,sandbox:S.sandbox,rows:S.pilot},null,2));
 }catch(err){toast(err.message,true);}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.dataset.filter){S[t.dataset.filter]=t.value;render();}else if(t.dataset.scenario){S[t.dataset.scenario]=Number(t.value);render();}else if(t.id==='record-type'){document.querySelectorAll('.shipment-field').forEach(x=>x.hidden=t.value!=='shipments');document.querySelectorAll('.visit-field').forEach(x=>x.hidden=t.value!=='visits');}else if(t.id==='csv-file'){const file=t.files[0];if(file){if(file.size>200000)throw new Error('CSV must be at most 200 KB');$('#csv-text').value=await file.text();S.import=null;$('#import-submit').disabled=true;previewImport();}}else if(t.id==='restore-file'){const file=t.files[0];if(file){if(file.size>500000)throw new Error('JSON restore must be at most 500 KB');const data=JSON.parse(await file.text());if(data.format!=='trialflow-workspace'||data.syntheticOnly!==true||data.workspace?.schemaVersion!==3)throw new Error('Choose a Trialflow v3 synthetic workspace export');restoreModal(null,data.workspace);}}}catch(err){toast(err.message,true);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){clearTimeout(searchTimer);const value=e.target.value,start=e.target.selectionStart;searchTimer=setTimeout(()=>{S.query=value;render();$('#search')?.focus();$('#search')?.setSelectionRange(start,start);},250);}else if(e.target.id==='csv-text'){S.import=null;if($('#import-submit'))$('#import-submit').disabled=true;}else if(e.target.dataset.scenario){const label=e.target.previousElementSibling;if(label?.querySelector('output'))label.querySelector('output').textContent=e.target.value+(e.target.dataset.scenario==='volume'?'%':e.target.dataset.scenario==='delay'?' workdays':'h');}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const data=new FormData(form),obj=Object.fromEntries(data),type=form.dataset.form,error=form.querySelector('.form-error');if(error)error.textContent='';const buttons=[...document.querySelectorAll(`button[form="${form.id}"],form[data-form="${type}"] button[type=submit],form[data-form="${type}"] button:not([type])`)];const previousDisabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{let openId=null;
 if(type==='initialize')await save('initialize',{syntheticAcknowledged:data.has('ack')});
 else if(type==='workflow'){openId=obj.id;await save('workflow',{id:obj.id,action:e.submitter?.value||'complete',reason:obj.reason});}
 else if(type==='reopen'){openId=obj.id;await save('workflow',{id:obj.id,action:'reopen',step:Number(obj.step),reason:obj.reason});}
 else if(type==='record'){const old=S.w.records.find(r=>r.id===obj.id);await save('records',{record:{...obj,id:obj.id||undefined,type:old?.type||obj.type,impact:Number(obj.impact),quantity:Number(obj.quantity),plannedVisits:Number(obj.plannedVisits)},reason:obj.reason,syntheticAcknowledged:data.has('ack'),resetEvidence:data.has('resetEvidence')});}
 else if(type==='study'){await save('studies',{study:{...obj,id:obj.id||undefined,visits:data.getAll('visits').map(Number),fresh:Number(obj.fresh),frozen:Number(obj.frozen),initialFrozen:Number(obj.initialFrozen),windowDays:Number(obj.windowDays),freshDays:data.getAll('freshDays').map(Number),frozenDays:data.getAll('frozenDays').map(Number),independentQC:data.has('independentQC')},reason:obj.reason});}
 else if(type==='settings'){await save('settings',{settings:{...obj,capacity:Number(obj.capacity),volume:Number(obj.volume),delay:Number(obj.delay),workdays:data.getAll('workdays').map(Number),holidays:obj.holidays.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)},reason:obj.reason});S.capacity=S.volume=S.delay=S.policy=null;}
 else if(type==='import'){if(!S.import||S.import.csv!==obj.csv||S.import.errors.length)throw new Error('Validate and preview this CSV before importing');await save('import',{csv:obj.csv,syntheticAcknowledged:data.has('ack')});}
 else if(type==='member'){await save('members',{...obj,roles:data.getAll('roles'),active:data.has('active'),memberVersion:Number(obj.memberVersion)});S.session=await api('session');}
 else if(type==='plan')await save('plan',{});
 else if(type==='snapshot')await save('snapshots',{name:obj.name});
 else if(type==='restore'){await save('restore',{...S.restore,confirm:obj.confirm,reason:obj.reason});}
 else if(type==='pilot-start')await save('pilot',{action:'start',task:obj.task,consent:data.has('consent')});
 else if(type==='pilot-finish')await save('pilot',{action:'finish',id:obj.id,outcome:obj.outcome,rating:Number(obj.rating),note:obj.note});
 close();render();if(openId)recordModal(openId);toast(S.sandbox?'Training change recorded in memory.':type==='workflow'?'Check saved. Dashboard updated.':'Saved. Workspace updated.');
 }catch(err){if(error){error.innerHTML=esc(err.message)+(err.details?.length?'<br>'+err.details.map(x=>`Row ${esc(x.row)}: ${esc(x.message)}`).join('<br>'):'');error.scrollIntoView({block:'nearest'});}else toast(err.message,true);if(err.status===409)toast('Refresh the workspace, review the latest changes, then try again.',true);}finally{buttons.forEach((b,i)=>b.disabled=previousDisabled[i]);}});
$('#refresh').addEventListener('click',()=>{if($('#dialog').open){close();toast('Closed the open form to refresh shared records.');}refresh();});
window.addEventListener('hashchange',()=>{close();render();$('#main').focus({preventScroll:true});});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))close();});
async function boot(){shell();try{S.session=await api('session');const w=await api('workspace');S.w=w.workspace;S.version=w.version;setConnection('Shared database · connected');}catch(e){S.session=null;S.w=null;S.error=e;setConnection(e.status===401?'Sign-in required':'Connection unavailable',!!e.status&&e.status!==401);}render();}
boot();setInterval(()=>{if(S.session&&!S.sandbox&&!$('#dialog').open&&!S.saving&&document.visibilityState==='visible'&&S.page!=='data')refresh(true);},20000);
